@st.cache_data(show_spinner=False)
def load_csv(path):
    p = Path(path)
    return pd.read_csv(p) if p.exists() else pd.DataFrame()

def show_image(name, caption=None):
    p = RESULTS / name
    if p.exists(): st.image(str(p), caption=caption, use_container_width=True)
    else: st.caption(f'Not found: {name}')

def dark(fig, height=360):
    fig.update_layout(template='plotly_dark', paper_bgcolor='rgba(0,0,0,0)', plot_bgcolor='rgba(0,0,0,0)', font=dict(color='#c7d6df'), margin=dict(l=10,r=10,t=50,b=10), height=height)
    return fig

